import org.springframework.data.domain.PageImpl;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Repository;
import org.springframework.util.StringUtils;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;




@Repository
@RequiredArgsConstructor
public class Xtw92RepositoryImpl implements Xtw92RepositoryCustom {
    private final JPAQueryFactory queryFactory;

    @Override
    public Page<Xtw92ResponseDto> findOrderBidsByFilters(String email, String bidStatus, String orderStatus, Pageable pageable) {
        QXtw92 orderBid = QXtw92.xtw92;
        QXhq12 order = QXhq12.xhq12;
        QXcc44 productSize = QXcc44.xcc44;
        QXvm17 productColor = QXvm17.xvm17;
        QXnr50 product = QXnr50.xnr50;
        QXdt35 productImage = QXdt35.xdt35;
        QXfr60 orderShipment = QXfr60.xfr60;
        QXjm45 user = QXjm45.xjm45;


        BooleanBuilder whereBuilder = new BooleanBuilder();


        if (StringUtils.hasText(email)) {
            whereBuilder.and(user.email.eq(email));
        }


        if (StringUtils.hasText(bidStatus)) {
            whereBuilder.and(orderBid.status.stringValue().eq(bidStatus));
        }


        if (StringUtils.hasText(orderStatus)) {
            whereBuilder.and(order.status.stringValue().eq(orderStatus));
        }


        List<Xtw92ResponseDto> content = queryFactory
                .select(Projections.constructor(
                        Xtw92ResponseDto.class,
                        orderBid.id,
                        product.id,
                        product.name,
                        product.englishName,
                        productSize.size,
                        productColor.colorName,
                        productImage.imageUrl,
                        orderBid.bidPrice,
                        orderBid.status.stringValue(),
                        order.status.stringValue(),
                        orderShipment.status.stringValue(),
                        orderBid.createdDate,
                        orderBid.modifiedDate
                ))
                .from(orderBid)
                .join(orderBid.user, user)
                .join(orderBid.productSize, productSize)
                .join(productSize.productColor, productColor)
                .join(productColor.product, product)
                .join(productColor.thumbnailImage, productImage)
                .leftJoin(orderBid.order, order)
                .leftJoin(order.orderShipment, orderShipment)
                .where(whereBuilder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();


        Long total = queryFactory
                .select(orderBid.id.count())
                .from(orderBid)
                .join(orderBid.user, user)
                .leftJoin(orderBid.order, order)
                .where(whereBuilder)
                .fetchOne();

        return new PageImpl<>(content, pageable, total != null ? total : 0L);
    }

    @Override
    public Xxn12Dto countOrderBidsByStatus(String email) {
        QXtw92 orderBid = QXtw92.xtw92;


        Long pendingCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.eq(Xkh73Status.PENDING)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        Long matchedCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.eq(Xkh73Status.MATCHED)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        Long cancelledOrCompletedCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.in(
                                Xkh73Status.CANCELLED, Xkh73Status.COMPLETED)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        pendingCount = pendingCount != null ? pendingCount : 0L;
        matchedCount = matchedCount != null ? matchedCount : 0L;
        cancelledOrCompletedCount = cancelledOrCompletedCount != null ? cancelledOrCompletedCount : 0L;

        return new Xxn12Dto(pendingCount, matchedCount, cancelledOrCompletedCount);
    }

    @Override
    public Xtw92ResponseDto findOrderBidById(Long orderBidId, String email) {
        QXtw92 orderBid = QXtw92.xtw92;
        QXhq12 order = QXhq12.xhq12;
        QXcc44 productSize = QXcc44.xcc44;
        QXvm17 productColor = QXvm17.xvm17;
        QXnr50 product = QXnr50.xnr50;
        QXdt35 productImage = QXdt35.xdt35;
        QXfr60 orderShipment = QXfr60.xfr60;
        QXjm45 user = QXjm45.xjm45;

        return queryFactory
                .select(Projections.constructor(
                        Xtw92ResponseDto.class,
                        orderBid.id,
                        product.id,
                        product.name,
                        product.englishName,
                        productSize.size,
                        productColor.colorName,
                        productImage.imageUrl,
                        orderBid.bidPrice,
                        orderBid.status.stringValue(),
                        order.status.stringValue(),
                        orderShipment.status.stringValue(),
                        orderBid.createdDate,
                        orderBid.modifiedDate
                ))
                .from(orderBid)
                .join(orderBid.user, user)
                .join(orderBid.productSize, productSize)
                .join(productSize.productColor, productColor)
                .join(productColor.product, product)
                .join(productColor.thumbnailImage, productImage)
                .leftJoin(orderBid.order, order)
                .leftJoin(order.orderShipment, orderShipment)
                .where(
                        orderBid.id.eq(orderBidId),
                        orderBid.user.email.eq(email)
                )
                .fetchOne();
    }

    @Override
    public Map<Long, Long> tradeCountByColorIds(List<Long> colorIds) {
        if (colorIds == null || colorIds.isEmpty()) {
            return Collections.emptyMap();
        }

        QXtw92 orderBid = QXtw92.xtw92;
        QXcc44 productSize = QXcc44.xcc44;

        List<Tuple> results = queryFactory.select(
                        productSize.productColor.id,
                        orderBid.id.count()
                )
                .from(orderBid)
                .join(orderBid.productSize, productSize)
                .where(
                        productSize.productColor.id.in(colorIds),
                        orderBid.status.eq(Xkh73Status.COMPLETED)
                )
                .groupBy(productSize.productColor.id)
                .fetch();

        return results.stream()
                .collect(Collectors.toMap(
                        t -> t.get(productSize.productColor.id),
                        t -> t.get(orderBid.id.count())
                ));
    }
}

