    private final JPAQueryFactory queryFactory;
    private final QXcm26 chatQuestion = QXcm26.xcm26;

    @Override
    public List<Xcm26> findRecentQuestionsByUserId(Long userId, int limit) {
        log.debug("사용자의 최근 질문 조회 쿼리 실행: userId={}, limit={}", userId, limit);

        return queryFactory
                .selectFrom(chatQuestion)
                .where(chatQuestion.user.id.eq(userId))
                .orderBy(chatQuestion.createdAt.desc())
                .limit(limit)
                .fetch();
    }

    @Override
    public List<Xcm26> findRecentQuestionsByClientIp(String clientIp, int limit) {
        log.debug("IP 주소별 최근 질문 조회 쿼리 실행: clientIp={}, limit={}", clientIp, limit);

        return queryFactory
                .selectFrom(chatQuestion)
                .where(
                        chatQuestion.clientIp.eq(clientIp)
                                .and(chatQuestion.user.isNull())
                )
                .orderBy(chatQuestion.createdAt.desc())
                .limit(limit)
                .fetch();
    }

    @Override
    public Page<Xcm26> searchQuestionsByKeyword(String keyword, Pageable pageable) {
        log.debug("키워드로 질문 검색 쿼리 실행: keyword={}, page={}, size={}",
                keyword, pageable.getPageNumber(), pageable.getPageSize());

        BooleanBuilder builder = new BooleanBuilder();


        if (StringUtils.hasText(keyword)) {
            builder.and(
                    chatQuestion.question.containsIgnoreCase(keyword)
                            .or(chatQuestion.answer.containsIgnoreCase(keyword))
            );
        }


        long total = queryFactory
                .selectFrom(chatQuestion)
                .where(builder)
                .fetchCount();


        List<Xcm26> results = queryFactory
                .selectFrom(chatQuestion)
                .where(builder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .orderBy(chatQuestion.createdAt.desc())
                .fetch();

        return new PageImpl<>(results, pageable, total);
    }
}



    @Override
    public Page<Xqr84> searchStandards(String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();

        if (keyword != null && !keyword.trim().isEmpty()) {
            builder.or(inspectionStandard.content.containsIgnoreCase(keyword))
                    .or(inspectionStandard.category.stringValue().containsIgnoreCase(keyword));
        }

        JPQLQuery<Xqr84> query = queryFactory
                .selectDistinct(inspectionStandard)
                .from(inspectionStandard)
                .leftJoin(inspectionStandardImage)
                .on(inspectionStandardImage.inspectionStandard.id.eq(inspectionStandard.id))
                .where(builder);


        if (pageable.getSort().isSorted()) {
            pageable.getSort().forEach(order -> {
                if (order.getProperty().equals("id")) {
                    if (order.isAscending()) {
                        query.orderBy(inspectionStandard.id.asc());
                    } else {
                        query.orderBy(inspectionStandard.id.desc());
                    }
                } else if (order.getProperty().equals("createdDate")) {
                    if (order.isAscending()) {
